t = int(input())
mod = 10 ** 9 + 7
for _ in range(t):
	(n, k) = map(int, input().split())
	n = n - 1
	if k % n == 0:
		z = k // n - 1
	else:
		z = k // n
	if z == 0:
		print((k - 1) % mod)
	else:
		l = (k * z - n * z * (z + 1) // 2) % mod
		print(((l - z) % mod + (k - 1) % mod) % mod)
